<template><el-card shadow="never" class="summary"><div class="headline"><div><el-tag type="success" effect="dark">{{ report.recommendation }}</el-tag><h2>{{ jobName }}</h2><p>{{ report.summary }}</p></div><div class="score"><strong>{{ report.overallScore }}</strong><span>综合胜任度</span></div></div><el-row :gutter="16" class="metrics"><el-col :span="8"><div><strong>{{ report.matchScore }}%</strong><span>岗位匹配度</span></div></el-col><el-col :span="8"><div><strong>{{ report.confidence }}%</strong><span>评估置信度</span></div></el-col><el-col :span="8"><div><strong>{{ report.competencyScores?.filter(i=>i.status==='达标').length }}/{{ report.competencyScores?.length }}</strong><span>能力达标</span></div></el-col></el-row><el-alert :title="report.generationNote" type="info" :closable="false" show-icon/></el-card></template>
<script setup>defineProps({report:{type:Object,required:true},jobName:{type:String,default:"目标岗位"}});</script>
